<?php
// PCW Freight mail relay: Apps Script -> this script -> server mail, From noreply@pcwfreight.com.
// Requests are signed with HMAC-SHA256 using a key generated by Apps Script (mailPair) and stored outside the web root.
header('Content-Type: application/json');
header('X-Robots-Tag: noindex');
const KEY_FILE = '/home/pcws3397/.pcw_mail_key';
const FROM = 'noreply@pcwfreight.com';
const MAX_TO = 5;

function out($a, $code = 200) { http_response_code($code); echo json_encode($a); exit; }
function clean($s, $n) { return substr(trim(preg_replace('/[\r\n]+/', ' ', (string)$s)), 0, $n); }

if ($_SERVER['REQUEST_METHOD'] !== 'POST') out(['ok' => false], 405);
$raw = file_get_contents('php://input');
if (strlen($raw) > 12000000) out(['ok' => false, 'error' => 'too_big'], 413);

if (isset($_GET['pair'])) {
  if (file_exists(KEY_FILE)) out(['ok' => false, 'error' => 'paired'], 409);
  $j = json_decode($raw, true);
  $k = isset($j['key']) ? (string)$j['key'] : '';
  if (!preg_match('/^[A-Za-z0-9_-]{40,200}$/', $k)) out(['ok' => false, 'error' => 'bad_key'], 400);
  if (file_put_contents(KEY_FILE, $k, LOCK_EX) === false) out(['ok' => false, 'error' => 'write'], 500);
  chmod(KEY_FILE, 0600);
  out(['ok' => true]);
}

if (!file_exists(KEY_FILE)) out(['ok' => false, 'error' => 'not_paired'], 503);
$key = trim(file_get_contents(KEY_FILE));
$sig = isset($_SERVER['HTTP_X_PCW_SIG']) ? $_SERVER['HTTP_X_PCW_SIG'] : '';
if (!$sig || !hash_equals(hash_hmac('sha256', $raw, $key), $sig)) out(['ok' => false, 'error' => 'sig'], 403);
$j = json_decode($raw, true);
if (!$j || !isset($j['ts']) || abs(round(microtime(true) * 1000) - (float)$j['ts']) > 300000) out(['ok' => false, 'error' => 'ts'], 403);

$to = array_values(array_filter(array_map('trim', explode(',', (string)$j['to']))));
if (!$to || count($to) > MAX_TO) out(['ok' => false, 'error' => 'to'], 400);
foreach ($to as $t) if (!filter_var($t, FILTER_VALIDATE_EMAIL)) out(['ok' => false, 'error' => 'to'], 400);
$subject = clean($j['subject'], 250);
$name = clean(isset($j['name']) ? $j['name'] : 'PCW Freight', 60);
$reply = clean(isset($j['replyTo']) ? $j['replyTo'] : '', 120);
if ($reply && !filter_var($reply, FILTER_VALIDATE_EMAIL)) $reply = '';
$body = (string)$j['body'];

$enc = function ($s) { return '=?UTF-8?B?' . base64_encode($s) . '?='; };
$headers = 'From: ' . $enc($name) . ' <' . FROM . ">\r\n";
if ($reply) $headers .= 'Reply-To: ' . $reply . "\r\n";
$headers .= "MIME-Version: 1.0\r\n";
$att = isset($j['att']) && is_array($j['att']) ? $j['att'] : [];
if ($att) {
  $b = 'pcw' . bin2hex(random_bytes(12));
  $headers .= 'Content-Type: multipart/mixed; boundary="' . $b . '"';
  $msg = "--$b\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . chunk_split(base64_encode($body));
  foreach ($att as $a) {
    $fn = preg_replace('/[^A-Za-z0-9._-]/', '_', (string)$a['n']);
    $ct = preg_match('#^[a-z]+/[a-z0-9.+-]+$#i', (string)$a['t']) ? $a['t'] : 'application/octet-stream';
    $msg .= "--$b\r\nContent-Type: $ct; name=\"$fn\"\r\nContent-Disposition: attachment; filename=\"$fn\"\r\nContent-Transfer-Encoding: base64\r\n\r\n" . chunk_split(preg_replace('/[^A-Za-z0-9+\/=]/', '', (string)$a['d']));
  }
  $msg .= "--$b--";
} else {
  $headers .= "Content-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64";
  $msg = chunk_split(base64_encode($body));
}
$ok = mail(implode(', ', $to), $enc($subject), $msg, $headers, '-f' . FROM);
out(['ok' => (bool)$ok], $ok ? 200 : 502);
